layout.layoutData:
// Set the label column. Default one is 0, the first one
var labelColumn = 0;
var id = String(settings.labelColumnId);
log.debug("label id == " + id);
if ((id != "null") && (id != ""))
  labelColumn = Number(id);

// Set the display column. Default one is 2, the third one.
var displayColumn = 2;
id = String(settings.displayColumnId);
if ((id != "null") && (id != ""))
  displayColumn = Number(id);

// Set the series Column. Default is 1, the second.
var seriesColumn = 1;
id = String(settings.seriesColumnId);
if ((id != "null") && (id != ""))
  seriesColumn = Number(id);
if (log.debugEnabled)
  log.debug("Columns in rows - " + labelColumn + "," + seriesColumn + "," + displayColumn);

// Validate input
if (isNaN(labelColumn)) throw "Setting 'labelColumnId' is not a number";
if (isNaN(displayColumn)) throw "Setting 'displayColumnId' is not a number";
if (isNaN(seriesColumn)) throw "Setting 'seriesColumnId' is not a number";

// Process integration connections
for (var icidx = 0; icidx < settings.ics.arrayLength; icidx++)
{
  log.debug("ic name is " + settings.ics[icidx]);

  // Find and execute the IntegrationComponent
  var ic = IntegrationComponent.getByName(settings.ics[icidx]);
  ic.execute();
  //log.debug("resultArray is " + ic.resultArray.describe());

  if (typeof icresults != 'undefined')
    icresults[icresults.arrayLength] = ic.resultArray;

  var records = ic.resultArray[0].record;
  // log.debug("adding ic result " + icidx + " , " + records.length);
  if (records) {
    addDataFromRecords(records);
  }
}

// log.debug("reportSeries == " + reportSeries.describe());

// Process integration services
for (var idx = 0; idx < settings.services.arrayLength; idx++)
{
  log.debug("Service name is " + settings.services[idx].name);

  var resultMap = settings.services[idx].execute();
  var result = resultMap.get("results");
  var records = result.record;

  // log.debug("adding service result " + idx + " , " + records.length);
  if (records) {
    addDataFromRecords(records);
  }
}

function addDataFromRecords(records) {
  for (var i = 0; i < records.length; i++) {

    var r = records[i];
    // Finding the label
    var labelValue = r.column[labelColumn].getText();
    // Finding the serie
    var seriesValue;
    if (seriesColumn >= 0)
      seriesValue = r.column[seriesColumn].getText();
    else
      seriesValue = r.column[displayColumn].getAttribute("name");

    // Finding display value
    var displayValue = r.column[displayColumn].getText();

    // Validating display value
    if (isNaN(displayValue))
      throw "display value for ic #" + icidx + ", row #" + i + " is not a number (was: " + displayValue + ")";

    addDataToSeries(seriesValue, findLabelId(labelValue), displayValue);
  }
}
